export type ParsedMigrateMeteoraDammLockLpTokenInstruction<
  TProgram extends string = typeof DYNAMIC_BONDING_CURVE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    virtualPool: TAccountMetas[0];
    /** migration_metadata */
    migrationMetadata: TAccountMetas[1];
    poolAuthority: TAccountMetas[2];
    pool: TAccountMetas[3];
    lpMint: TAccountMetas[4];
    lockEscrow: TAccountMetas[5];
    owner: TAccountMetas[6];
    sourceTokens: TAccountMetas[7];
    escrowVault: TAccountMetas[8];
    ammProgram: TAccountMetas[9];
    aVault: TAccountMetas[10];
    bVault: TAccountMetas[11];
    aVaultLp: TAccountMetas[12];
    bVaultLp: TAccountMetas[13];
    aVaultLpMint: TAccountMetas[14];
    bVaultLpMint: TAccountMetas[15];
    /** token_program */
    tokenProgram: TAccountMetas[16];
  };
  data: MigrateMeteoraDammLockLpTokenInstructionData;
};

export function parseMigrateMeteoraDammLockLpTokenInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedMigrateMeteoraDammLockLpTokenInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 17) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 17,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      virtualPool: getNextAccount(),
      migrationMetadata: getNextAccount(),
      poolAuthority: getNextAccount(),
      pool: getNextAccount(),
      lpMint: getNextAccount(),
      lockEscrow: getNextAccount(),
      owner: getNextAccount(),
      sourceTokens: getNextAccount(),
      escrowVault: getNextAccount(),
      ammProgram: getNextAccount(),
      aVault: getNextAccount(),
      bVault: getNextAccount(),
      aVaultLp: getNextAccount(),
      bVaultLp: getNextAccount(),
      aVaultLpMint: getNextAccount(),
      bVaultLpMint: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getMigrateMeteoraDammLockLpTokenInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
